def transform(wb):
    ws = wb['Sheet1']
    limit = ws.max_row
    if limit is None:
        limit = 82
    if limit > 82:
        limit = 82
    if limit < 1:
        limit = 82
    blocks = []
    start = None
    end = None
    for r in range(1, limit + 1):
        a = ws.cell(row=r, column=1).value
        b = ws.cell(row=r, column=2).value
        nonblank = False
        if a is not None and str(a).strip() != '':
            nonblank = True
        if b is not None and str(b).strip() != '':
            nonblank = True
        if nonblank:
            if start is None:
                start = r
            end = r
        else:
            if start is not None:
                blocks.append((start, end))
                start = None
                end = None
    if start is not None:
        blocks.append((start, end))
    for block in blocks:
        start = block[0]
        end = block[1]
        a0 = ws.cell(row=start, column=1).value
        b0 = ws.cell(row=start, column=2).value
        data_start = start
        if a0 is not None and b0 is not None and str(a0).strip() == 'Number' and str(b0).strip() == 'Name':
            data_start = start + 1
        if data_start > end:
            continue
        rows = []
        for r in range(data_start, end + 1):
            a = ws.cell(row=r, column=1).value
            b = ws.cell(row=r, column=2).value
            key = ''
            if a is not None:
                key = str(a)
            rows.append((key, r, a, b))
        rows.sort()
        i = 0
        for item in rows:
            a = item[2]
            b = item[3]
            ws.cell(row=data_start + i, column=1).value = a
            ws.cell(row=data_start + i, column=2).value = b
            i = i + 1
